<template>
  <div class="desktop-analytics min-w-0 space-y-5">
    <nav class="flex gap-3" :aria-label="t('biNative.period')"><button v-for="k in ['day','week','month'] as const" :key="k" class="btn" :class="kind === k ? 'btn-primary' : 'btn-secondary'" :aria-pressed="kind === k" @click="kind = k">{{ t(`biNative.${k}`) }}</button></nav>
    <DesktopDailyReports v-if="kind === 'day'" :organization-id="organizationId" :self-managed="selfManaged === true" :enabled="enabled" :analysis-model="analysisModel" :initial-date="initialDate" />
    <template v-else><div class="card p-5 space-y-4"><p>{{ t('biNative.periodHint') }}</p><p class="text-sm text-gray-500">{{ t('biNative.automaticHint') }}</p><p>{{ t(kind === 'week' ? 'biNative.weeklyAuto' : 'biNative.monthlyAuto') }}: {{ (kind === 'week' ? weeklyEnabled : monthlyEnabled) ? t('common.enabled') : t('common.disabled') }}</p><label class="block">{{ t('biNative.periodStart') }}<input v-model="start" type="date" class="input mt-2 max-w-xs" /></label><div class="flex flex-wrap gap-2"><button class="btn btn-secondary" :disabled="loading || !validStart" @click="load()">{{ t('common.refresh') }}</button><template v-if="!selfManaged"><button v-for="mode in ['generate','retry','regenerate']" :key="mode" class="btn btn-secondary" :disabled="busy || !enabled || !validStart" @click="run(mode)">{{ t(`biNative.${mode}`) }}</button></template></div><p class="text-sm text-gray-500">{{ t('biNative.waitingHint') }}</p><p v-if="error" role="alert" class="text-red-600">{{ error }}</p></div>
      <div class="grid min-w-0 gap-5 lg:grid-cols-[280px_minmax(0,1fr)]"><aside class="card p-5 space-y-3" :aria-busy="loading"><h2 class="font-semibold">{{ t('biNative.allVersions') }}</h2><p v-if="loading" role="status">{{ t('common.loading') }}</p><p v-if="!loading && !reports.length && !error">{{ t('biNative.noData') }}</p><button v-for="report in reports" :key="report.id" class="w-full rounded border p-3 text-left" :class="selected === report.id ? 'border-primary-500' : 'border-gray-200 dark:border-dark-700'" @click="select(report.id)"><span class="block">{{ report.range.start_date }} — {{ report.range.end_date }}</span><span class="mt-2 block text-sm">v{{ report.revision }} · {{ report.status }}</span></button><button v-if="more" class="btn btn-secondary" :disabled="loading" @click="load(page + 1)">{{ t('bi.loadMore') }}</button></aside>
        <section class="card min-w-0 p-5 space-y-4" :aria-busy="detailLoading"><p v-if="detailLoading" role="status">{{ t('common.loading') }}</p><div v-if="detailError" role="alert"><p>{{ detailError }}</p><button class="btn btn-secondary" @click="select(selected)">{{ t('biNative.retry') }}</button></div><p v-if="!selected">{{ t('biNative.selectReport') }}</p><template v-if="detail"><dl class="grid gap-3 sm:grid-cols-3"><div><dt>{{ t('biNative.status') }}</dt><dd>{{ detail.report.status }}</dd></div><div><dt>{{ t('biNative.version') }}</dt><dd>{{ detail.report.revision }}</dd></div><div><dt>{{ t('biNative.model') }}</dt><dd class="break-all">{{ detail.report.model }}</dd></div></dl><p v-if="detail.report.source_changed" class="text-amber-700">{{ t('biNative.sourceChanged') }}</p><div v-for="field in ['available_dates','partial_dates','missing_dates','no_record_dates'] as const" :key="field"><p>{{ t(`biNative.${({available_dates:'available',partial_dates:'partial',missing_dates:'missing',no_record_dates:'noRecords'} as const)[field]}`) }}: {{ detail.report.coverage[field]?.join('、') || '—' }}</p></div><p v-for="(reason,date) in detail.report.coverage.reasons" :key="date" class="text-sm text-gray-500">{{ date }} · {{ reason }}</p><article class="report-content" @click="onSourceReference" v-html="markdown(detail.content || '', detail.summary_outline?.validated_source_dates)" /><button v-if="detail.content" class="btn btn-secondary" @click="copy">{{ t('common.copy') }}</button><p role="status">{{ copyStatus }}</p><h3 class="font-semibold">{{ t('biNative.sources') }}</h3><div v-if="sourceError" role="alert"><p>{{ sourceError }}</p><button class="btn btn-secondary" @click="loadSources()">{{ t('biNative.retry') }}</button></div><button v-for="source in sources" :key="source.date" class="block w-full rounded border p-3 text-left" @click="openSource(source.date)">{{ source.date }} · v{{ source.revision }} · {{ source.status }}</button><button v-if="sourceMore" class="btn btn-secondary" @click="loadSources(sourcePage + 1)">{{ t('bi.loadMore') }}</button><div v-if="sourceDetail" class="border-t pt-4"><h4>{{ sourceDetail.date }} · v{{ sourceDetail.revision }}</h4><article class="report-content" v-html="markdown(sourceDetail.content || '')" /></div></template></section>
      </div>
    </template>
  </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import DesktopDailyReports from './DesktopDailyReports.vue'
import DOMPurify from 'dompurify'
import { marked } from 'marked'
import { desktopPeriods, lastClosedPeriod, type PeriodReport, type PeriodSource } from '@/api/desktopPeriods'
const props = defineProps<{ organizationId: string; selfManaged?: boolean; enabled: boolean; analysisModel: string; weeklyEnabled?: boolean; monthlyEnabled?: boolean; initialKind?: string; initialStart?: string; initialReportId?: string; initialDate?: string }>()
const { t } = useI18n(), kind = ref<'day' | 'week' | 'month'>(props.initialKind === 'week' || props.initialKind === 'month' ? props.initialKind : 'day'), start = ref(props.initialStart || (props.initialKind === 'week' || props.initialKind === 'month' ? lastClosedPeriod(props.initialKind) : '')), reports = ref<PeriodReport[]>([]), page = ref(1), more = ref(false), loading = ref(false), error = ref(''), busy = ref(false), selected = ref(''), detail = ref<{ report: PeriodReport; content: string | null; summary_outline?: {sections:{kind:string;title:string;start_line:number;end_line:number;source_dates:string[]}[];validated_source_dates:string[];unverified_source_dates:string[]} }>(), detailLoading = ref(false), detailError = ref(''), sources = ref<PeriodSource[]>([]), sourceMore = ref(false), sourcePage = ref(1), sourceError = ref(''), sourceDetail = ref<PeriodSource>(), copyStatus = ref('')
let generation = 0, listGeneration = 0, detailGeneration = 0, sourceGeneration = 0
const api = () => desktopPeriods(props.organizationId, props.selfManaged)
const validStart = computed(() => { if (!/^\d{4}-\d{2}-\d{2}$/.test(start.value) || kind.value === 'day') return false; const d = new Date(start.value+'T00:00:00+08:00'); return !Number.isNaN(d.getTime()) && (kind.value === 'week' ? new Date(d.getTime()+8*3600000).getUTCDay() === 1 : start.value.endsWith('-01')) && start.value <= lastClosedPeriod(kind.value) })
function markdown(text: string, dates: string[] = []) {
  const linked = text.replace(/\[日总结:(\d{4}-\d{2}-\d{2})\]/g, (original, date: string) => dates.includes(date) ? `[日总结:${date}](#frozen-source-${date})` : original)
  return DOMPurify.sanitize(marked.parse(linked, { async: false }) as string)
}
function onSourceReference(event: MouseEvent) {
  const target = event.target instanceof Element ? event.target.closest('a[href^="#frozen-source-"]') : null
  const date = target?.getAttribute('href')?.replace('#frozen-source-', '')
  if (date && detail.value?.summary_outline?.validated_source_dates.includes(date)) { event.preventDefault(); void openSource(date) }
}
function message(cause: unknown) { return t((cause as { status?: number }).status === 423 ? 'biNative.stepUp' : 'biNative.failed') }
async function load(next = 1) { if (!validStart.value) return; const g = generation, n = ++listGeneration; loading.value = true; error.value = ''; try { const value = await api().list(kind.value,start.value,next); if (g !== generation || n !== listGeneration) return; reports.value = next === 1 ? value.items : [...reports.value,...value.items]; page.value = next; more.value = value.has_more; if (!selected.value && value.items[0]) void select(value.items[0].id) } catch (cause) { if (g === generation && n === listGeneration) error.value = message(cause) } finally { if (g === generation && n === listGeneration) loading.value = false } }
async function select(id: string) { selected.value = id; detail.value = undefined; sources.value = []; sourceDetail.value = undefined; detailError.value = ''; sourceError.value = ''; copyStatus.value = ''; const g = generation, n = ++detailGeneration; sourceGeneration++; detailLoading.value = true; try { const value = await api().detail(id); if (g !== generation || n !== detailGeneration) return; detail.value = value; void loadSources() } catch (cause) { if (g === generation && n === detailGeneration) detailError.value = message(cause) } finally { if (g === generation && n === detailGeneration) detailLoading.value = false } }
async function loadSources(next = 1) { const id = selected.value, g = generation, n = ++sourceGeneration; sourceError.value = ''; try { const value = await api().sources(id,next); if (g !== generation || n !== sourceGeneration || id !== selected.value) return; sources.value = next === 1 ? value.items : [...sources.value,...value.items]; sourcePage.value = next; sourceMore.value = value.has_more } catch (cause) { if (g === generation && id === selected.value) sourceError.value = message(cause) } }
async function openSource(date: string) { const id = selected.value, g = generation, n = ++sourceGeneration; sourceDetail.value = undefined; sourceError.value = ''; try { const value = await api().source(id,date); if (g === generation && n === sourceGeneration && id === selected.value) sourceDetail.value = value } catch (cause) { if (g === generation && n === sourceGeneration) sourceError.value = message(cause) } }
async function run(mode: string) { if (mode === 'regenerate' && !window.confirm(t('biNative.confirmRegenerate'))) return; busy.value = true; const g = generation; try { await api().run(kind.value,start.value,mode); if (g === generation) { selected.value = ''; detail.value = undefined; await load() } } catch (cause) { if (g === generation) error.value = message(cause) } finally { if (g === generation) busy.value = false } }
async function copy() { const id = selected.value, g = generation; try { const value = await api().detail(id); if (g !== generation || id !== selected.value || !value.content) return; await navigator.clipboard.writeText(value.content); copyStatus.value = t('biNative.copied') } catch { copyStatus.value = t('biNative.copyFailed') } }
watch([kind, () => props.organizationId], () => { generation++; reports.value = []; selected.value = ''; detail.value = undefined; sources.value = []; sourceDetail.value = undefined; loading.value = false; detailLoading.value = false; busy.value = false; error.value = ''; if (kind.value !== 'day') start.value = lastClosedPeriod(kind.value) })
watch(start, () => { generation++; reports.value = []; selected.value = ''; detail.value = undefined; sources.value = []; sourceDetail.value = undefined; void load() })
if (kind.value !== 'day') { void load(); if (props.initialReportId) void select(props.initialReportId) }
onBeforeUnmount(() => { generation++ })
</script>
